def _apply_discount(price, discount_type, value):
    if price < 0:
        raise ValueError('negative price')
    if discount_type == 'percentage':
        return round(price * (1 - value / 100), 2)
    if discount_type == 'fixed':
        return round(max(price - value, 0), 2)
    if discount_type == 'bogo':
        if value < 1:
            return 0
        return round((value // 2 + value % 2) * price, 2)
    raise ValueError('unknown discount type')


def percentage_discount(price, percent):
    return _apply_discount(price, 'percentage', percent)


def fixed_discount(price, amount):
    return _apply_discount(price, 'fixed', amount)


def bogo_discount(price, quantity):
    return _apply_discount(price, 'bogo', quantity)


def chained_discounts(price, steps):
    if price < 0:
        raise ValueError('negative price')
    result = price
    for discount_type, value in steps:
        result = _apply_discount(result, discount_type, value)
    return result
